import{_ as r,a as e,c as a,ac as o}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 36 明夷：受伤的光明如何保存至38 睽：差异不必变成敌意","description":"逐卦核读《周易》与《周易正义》，从退进之际读到家人分歧、遇险知止与解难。","frontmatter":{"title":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 36 明夷：受伤的光明如何保存至38 睽：差异不必变成敌意","description":"逐卦核读《周易》与《周易正义》，从退进之际读到家人分歧、遇险知止与解难。","splitFrom":"life/personal/yijing/hexagrams-33-40.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解","summary":"逐卦核读《周易》与《周易正义》，从退进之际读到家人分歧、遇险知止与解难。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 33 遯：退避也需要判断至35 晋：被看见之后如何进取","link":"/life/personal/yijing/hexagrams-33-40-part-01"},"next":{"text":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 39 蹇：看见险阻而能停下至比较与自测","link":"/life/personal/yijing/hexagrams-33-40-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 33 遯：退避也需要判断至35 晋：被看见之后如何进取","link":"/life/personal/yijing/hexagrams-33-40-part-01"},"next":{"text":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 39 蹇：看见险阻而能停下至比较与自测","link":"/life/personal/yijing/hexagrams-33-40-part-03"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-33-40-part-02.md","filePath":"life/personal/yijing/hexagrams-33-40-part-02.md"}'),n={name:"life/personal/yijing/hexagrams-33-40-part-02.md"};function d(s,t,i,p,g,l){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="六十四卦详读-三十三至四十-遯、大壮、晋、明夷、家人、睽、蹇、解-·-36-明夷-受伤的光明如何保存至38-睽-差异不必变成敌意" tabindex="-1">六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 36 明夷：受伤的光明如何保存至38 睽：差异不必变成敌意 <a class="header-anchor" href="#六十四卦详读-三十三至四十-遯、大壮、晋、明夷、家人、睽、蹇、解-·-36-明夷-受伤的光明如何保存至38-睽-差异不必变成敌意" aria-label="Permalink to &quot;六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 36 明夷：受伤的光明如何保存至38 睽：差异不必变成敌意&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-33-40">返回分篇目录</a></p><p>本篇将经文、传文与现代概括分开：<strong>卦辞、爻辞</strong>是《周易》经文，<strong>大象</strong>出自《象传》；表中解释和“读法”是依据原文及古注所作的现代概括。爻从下向上读，初爻并不必然代表某个年龄，上爻也不是固定的结局。古注采用王弼注、孔颖达疏《周易正义》，它是重要的解释传统，不是经文的唯一可能含义。所引古籍为公有领域文本；电子本中的异体字、断句仍须留意。</p><p>这一组可成对比较：遯与大壮讨论退与强，晋与明夷讨论光明的显与藏，家人与睽讨论共同生活与分歧，蹇与解讨论困阻与舒解。“吉凶”保留为古代占筮判断，不作现实事件的科学预测。</p><h2 id="gua-36" tabindex="-1">36 明夷：受伤的光明如何保存 <a class="header-anchor" href="#gua-36" aria-label="Permalink to &quot;36 明夷：受伤的光明如何保存 {#gua-36}&quot;">​</a></h2><p><strong>卦符：䷣｜上卦坤 ☷（地），下卦离 ☲（火、明）。</strong> 光明在地中，与晋的结构相倒。“夷”在《正义》中释为伤，主题是明受到压抑时的处境。</p><p><strong>卦辞原文：</strong></p><blockquote><p>明夷：利艱貞。</p></blockquote><p><strong>白话概括：</strong> 在艰难中保持正当。《彖传》援引文王和箕子，《正义》据此解释为昏暗政治下有德者收敛外在锋芒、保守内在志向。这是传统政治解读；经文各爻的鸟、伤股、狩猎等意象不应被抹去。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九</td><td>明夷于飛，垂其翼。君子于行，三日不食，有攸往，主人有言。</td><td>飞鸟垂翼，出行者艰苦且遭议论，表现早期受伤与离去代价；不是鼓励禁食或拒绝求助。</td></tr><tr><td>六二</td><td>明夷，夷于左股，用拯馬壯，吉。</td><td>左腿受伤，需要健壮马匹救助；重点是受损后及时救援，不是根据爻位诊断身体疾病。</td></tr><tr><td>九三</td><td>明夷于南狩，得其大首，不可疾貞。</td><td>狩猎而获得主要目标，古注联系除去昏暗根源；后句提醒不能急迫求成，政治类比须限定历史背景。</td></tr><tr><td>六四</td><td>入于左腹，獲明夷之心，于出門庭。</td><td>深入到内部、看清暗害的心意，继而离开；难解处在入腹与出门的主体，宜保留象征阅读余地。</td></tr><tr><td>六五</td><td>箕子之明夷，利貞。</td><td>以箕子在困境中保存志向为典型；不能因此要求受伤害者无限忍耐。</td></tr><tr><td>上六</td><td>不明晦，初登于天，後入于地。</td><td>从登天到入地，写昏暗最终失去准则；它不与前面受伤而守明的人物完全同类。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>明入地中，明夷；君子以蒞眾，用晦而明。</p></blockquote><p><strong>大象解释：</strong> 面对众人不以苛察和炫耀聪明为能，外表留有余地，内在仍明辨是非。“晦”不是欺骗他人的通行许可。</p><p><strong>整体读法与误区：</strong> 本卦同时容纳退离、救援、识别根源与保存志向等不同反应，不是一张“隐忍到底”的处方。现代读者可讨论显露才智的情境与安全边界，但现实中的暴力、伤害和压迫需要现实支持。把“用晦”理解成放弃判断，或把所有困境美化成磨炼，都会失去“明不可息”的文本重心。</p><p><strong>经传对读：</strong> 初九以鸟翼写伤，六二写腿伤，六四进入腹心，最后上六从高处落地，人物和视角不断变化。尤其《小象》为六五说“明不可息”，为上六说“失则”，已经区分保存光明者与失去准则者。逐爻应先辨是谁受伤、谁造成昏暗，避免把六爻统一套成一个人的忍耐历程。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%98%8E%E5%A4%B7" target="_blank" rel="noopener noreferrer">《周易·明夷》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/04%E6%98%8E%E5%A4%B7" target="_blank" rel="noopener noreferrer">《周易正义》卷四·明夷</a>。</p><h2 id="gua-37" tabindex="-1">37 家人：共同生活从言行开始 <a class="header-anchor" href="#gua-37" aria-label="Permalink to &quot;37 家人：共同生活从言行开始 {#gua-37}&quot;">​</a></h2><p><strong>卦符：䷤｜上卦巽 ☴（风），下卦离 ☲（火）。</strong> 风与火内外相成，《正义》据此说明家内成员互相影响。此处“家”兼有古代宗法、经济与礼制组织的含义。</p><p><strong>卦辞原文：</strong></p><blockquote><p>家人：利女貞。</p></blockquote><p><strong>白话概括：</strong> 卦辞强调女性在家内的贞正，古注进一步采用男外女内的分工解释。阅读时应明确这是古代性别秩序，不是今天所有家庭必须采用的制度；现代可讨论责任、信任与言行一致，但不可把转换后的观点冒充原文已包含的平等观。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九</td><td>閑有家，悔亡。</td><td>“闲”有防范、设界之义，及早形成共同生活的规矩；不等于以监视或隔绝来管理家人。</td></tr><tr><td>六二</td><td>无攸遂，在中饋，貞吉。</td><td>处在家内供应饮食的角色，不独自追求外事；应看见古代劳动分工，不把它规定为女性天职。</td></tr><tr><td>九三</td><td>家人嗃嗃，悔厲吉；婦子嘻嘻，終吝。</td><td>严厉管束与失去节度的嬉笑相对；文字带有古代父权尺度，不能为辱骂、恐吓或家暴背书。</td></tr><tr><td>六四</td><td>富家，大吉。</td><td>使家庭资源充实、生活得到支持；联系全卦可理解为担负责任，而非只以财富判断家庭价值。</td></tr><tr><td>九五</td><td>王假有家，勿恤。吉。</td><td>王者到达或成就有序之家，“假”通至；《小象》说“交相爱”，补出互相关爱的面向。</td></tr><tr><td>上九</td><td>有孚威如，終吉。</td><td>信实与庄重并存；《小象》把“威”的根基归于反身自省，而非单向要求别人服从。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>風自火出，家人；君子以言有物，而行有恆。</p></blockquote><p><strong>大象解释：</strong> 说话有实际内容，行动有稳定准则。《正义》从近处、小事说起：家庭的影响由每天可见的言行形成，不靠偶尔的大道理。</p><p><strong>整体读法与误区：</strong> 家人卦有严的一面，也有“交相爱”“反身”的一面；既不能洗去其宗法背景，也不能只截取严厉文字当作家教秘诀。今天可以把“言有物、行有恒”转为成员共同承担的要求，检验承诺是否兑现、规则是否双向、照料劳动是否被看见。这是批判性继承，而不是复制古代家长权力。</p><p><strong>经传对读：</strong> 卦辞强调“女贞”，大象却把言行要求交给“君子”；《彖传》又说父母都是家中严君，并非只要求一个成员负责。九五的“交相爱”和上九的“反身”，还可用来反问严厉是否首先作用于主事者自身。这样读能同时看见古代等级秩序及其对责任承担者的约束，而不只摘录服从。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%AE%B6%E4%BA%BA" target="_blank" rel="noopener noreferrer">《周易·家人》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/04%E5%AE%B6%E4%BA%BA" target="_blank" rel="noopener noreferrer">《周易正义》卷四·家人</a>。</p><h2 id="gua-38" tabindex="-1">38 睽：差异不必变成敌意 <a class="header-anchor" href="#gua-38" aria-label="Permalink to &quot;38 睽：差异不必变成敌意 {#gua-38}&quot;">​</a></h2><p><strong>卦符：䷥｜上卦离 ☲（火），下卦兑 ☱（泽）。</strong>“睽”读 kuí，有乖离、相背之义。火趋上、泽趋下，是共同处境中方向不同的象。</p><p><strong>卦辞原文：</strong></p><blockquote><p>睽：小事吉。</p></blockquote><p><strong>白话概括：</strong> 意见相背时，较小、可行的事情仍有实现的可能。《正义》明确区分需要众力的大事与不待众力的小事，因此“小事吉”不是说人生只能做小事，而是提示合作条件尚不足。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九</td><td>悔亡，喪馬勿逐，自復；見惡人无咎。</td><td>失马不必穷追，接触不喜欢的人也未必有过；不应把暂时分离或个人嫌恶直接升级成敌我判断。</td></tr><tr><td>九二</td><td>遇主于巷，无咎。</td><td>在巷中相遇，表示正式途径之外仍能沟通；“无咎”不是对一切秘密交易的认可。</td></tr><tr><td>六三</td><td>見輿曳，其牛掣，其人天且劓，无初有終。</td><td>车被拖、牛受制，人又受刑，开端困顿而后有终。“掣”据通行异文；“天”所指刑罚有训释争论。</td></tr><tr><td>九四</td><td>睽孤，遇元夫，交孚，厲无咎。</td><td>孤立之中遇到可以信赖的人，以互信渡过危险；不是逢人即认定为命定知己。</td></tr><tr><td>六五</td><td>悔亡，厥宗噬膚，往何咎。</td><td>同宗之间的阻隔如咬开柔软皮肉，联系恢复；古注由此说明接近相应者不难。</td></tr><tr><td>上九</td><td>睽孤，見豕負涂，載鬼一車，先張之弧，後說之弧，匪寇婚媾，往遇雨則吉。</td><td>把对方看成污猪、鬼车，先张弓后释弓，终于认出并非敌寇；“鬼”在这里不构成灵异事实证据。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>上火下澤，睽；君子以同而異。</p></blockquote><p><strong>大象解释：</strong> 在共同原则中容纳不同职责和表现。《正义》以共同治事而职掌有别说明，并非要求人人思想和生活方式一致。</p><p><strong>整体读法与误区：</strong> 上九尤其适合细读：外在所见、内心怀疑、采取武力和后来识别，依次展开。全卦并不保证所有冲突都是误会，而是让人检查敌意形成的过程。现代可先确认事实、缩小合作范围、允许合理分歧；若只说“求同存异”却不处理现实伤害，同样是把古文读成空话。</p><p><strong>经传对读：</strong>“无初有终”与“先张之弧，后说之弧”都呈现判断的前后改变；后者还由“遇雨”转到《小象》的“群疑亡”。雨在这里与猜疑解除相连，可以先按叙事转折理解。初九见恶人、九四遇元夫又提醒，接触、信任和认同并不是同一个层次，不宜合并成凡遇皆吉。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%9D%BD" target="_blank" rel="noopener noreferrer">《周易·睽》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/04%E7%9D%BD" target="_blank" rel="noopener noreferrer">《周易正义》卷四·睽</a>。</p>',43)])])}const k=r(n,[["render",d]]);export{c as __pageData,k as default};
